mapper.select:
SELECT id, report_no AS reportNo, report_type AS reportType, period,
       file_path AS filePath, status, generate_time AS generateTime
FROM rpt_report WHERE id = #{id}

SELECT id, report_no AS reportNo, report_type AS reportType, period, file_path AS filePath, status, generate_time AS generateTime FROM rpt_report WHERE 1 = 1
AND report_type = #{reportType}
AND period = #{period}
ORDER BY generate_time DESC, id DESC
